#!/usr/bin/env python3
"""Temporary: apply the 11 Nov wording fixes to the stored history.html.

history.html is regenerated by the nightly run from news-engine
site/history_html.py, which already carries these strings. Until the
nightly runs, the 5-minute build copies the stored file, so we rewrite
the old strings here. Every replacement is a no-op once the nightly has
regenerated the page (old strings no longer occur). Remove this script
and its call in build.yml after the 12 Nov nightly.
"""
import pathlib
import sys

PAIRS = [
    ("Severe News Share (rank)</h2>",
     "Severe News Share</h2>"),
    ("Rank of the day's Severe News Share against comparable days (0–100; the share is each source's share of notable stories at the top grade, averaged over sources), 7-day average",
     "How much of the day's news is at the most serious level (0–100 against comparable days), 7-day average"),
    ("Each source's share of notable stories in its largest topic, averaged over sources (dark), and its usual value (grey), in %",
     "How much of the news is on one topic, in % (dark: the day; grey: usual)"),
    ("How much more widely than usual the day's top topic is covered: the topic furthest above its usual number of sources (0–100 against comparable days)",
     "How far the day's top topic stands above its usual coverage (0–100 against comparable days)"),
    ("Every 0–100 reading compares the day with comparable days: the same kind of day (weekday or weekend) in the previous 26 weeks, for News Sentiment the previous year; 50 is a typical day.",
     "Every reading from 0 to 100 compares the day with the same kind of day (weekday or weekend) in the previous 26 weeks, or for News Sentiment the previous year. 50 is a typical day."),
    # stale nav label, from the earlier patch
    ('methodology.html">Methods<', 'methodology.html">Methodology<'),
]

def main(path):
    p = pathlib.Path(path)
    if not p.exists():
        return
    s = p.read_text()
    n = 0
    for old, new in PAIRS:
        if old in s:
            s = s.replace(old, new)
            n += 1
    p.write_text(s)
    print(f"history_text_patch: {n} replacements applied")

if __name__ == "__main__":
    main(sys.argv[1])
